end
end
for Qn,Rn in pairs(Gn.usage and Gn.usage.possible_rewards or{})do
local Sn=Rn.unit or Rn.item
if Sn and H.Units[Sn]and H.Units[Sn].rarity==ttc[1675]and not Mn[Sn]then
table.insert(Kn.units,N.name(Sn))
end
end
table.sort(Kn.units)
local Tn={}
if#Fn.missing>0 then
local Un=Fn.missing[1]
table.insert(Tn,string.format(ttc[1677],Un.name,Un.unitName))
end
if#Kn.units>0 then
table.insert(Tn,string.format(ttc[1678],table.concat(Kn.units,ttc[1530])))
end
Kn.why=table.concat(Tn,ttc[1679])
