if zo then
J.str.reequip={uuid=yo.unit,slot=zo}
j.saveNow()
j.request(ttc[1700],ttc[1701],yo.unit)
local Ao=M.now()
while M.now()-Ao<4 and db.slotOf(yo.unit)do
task.wait(0.25)
end
end
local Bo=M.now()
local Co,Do=j.request(ttc[1702],ttc[1703],yo.uuid,{unit_uuid=yo.unit})
local function Eo()
local Fo=qo.collection:get_unit_by_uuid(yo.unit)
return Fo and Fo.skin~=nil
end
while M.now()-Bo<5 and not Eo()do
task.wait(0.25)
end
if zo then
db.reequip()
end
if Eo()then
j.log(1,ttc[1631],string.format(ttc[1704],yo.name,yo.unitName))
P.pickNote.skins=nil
xo=eb.skinPlan()
else
local Go=j.gameSaid(Bo)
P.pickNote.skins=string.format(ttc[1705],yo.name,tostring(Go or Do or ttc[1698]))
j.log(1,ttc[1631],P.pickNote.skins)
j.backoff(ttc[1702],1800)
end
end
if#xo.sell>0 then
