end
R.add(string.format(ttc[1709],#Ho),#Ho,ttc[1699],string.format(ttc[1710],M.fmt(Oo)))
P.pickNote.skins=nil
end
end
if I.starOpen then
local Po=qo.inventory
local function Qo()
