local hx=gx.trust and not gx.trust.ok
ex.why=(ex.why or ttc[363])..ttc[1898]..(hx and string.format(gx.trust.ratio<0.1 and ttc[1899]or ttc[1900],gx.trust.ratio)or tostring(gx.playing or gx.margin))
end
if ex.train then
ex.why=(ex.why or ttc[363])..string.format(ttc[1901],math.floor(ex.train+0.5))
end
end
table.sort(cx,function(ix,jx)
return ix.score>jx.score
end)
for kx,lx in ipairs(cx)do
if lx.kind==ttc[1454]and lx.started then
if kx>1 and cx[1].kind~=ttc[1586]then
table.remove(cx,kx)
table.insert(cx,1,lx)
lx.why=ttc[1902]..(lx.why or ttc[363])
