local nx,ox={},{}
for px,qx in ipairs(cx)do
if qx~=mx then
if O.dropsGoal(qx)or qx.train then
qx.why=ttc[1903]..(qx.why or ttc[363])
table.insert(nx,qx)
else
table.insert(ox,qx)
end
end
end
if#nx>0 then
cx={}
if mx then
table.insert(cx,mx)
end
for rx,sx in ipairs(nx)do
table.insert(cx,sx)
end
for tx,ux in ipairs(ox)do
table.insert(cx,ux)
end
end
end
for vx,wx in ipairs(cx)do
if wx.kind==ttc[1588]then
local xx=cx[1]
if vx>1 and xx.kind~=ttc[1586]and not(xx.kind==ttc[1454]and xx.started)then
table.remove(cx,vx)
table.insert(cx,1,wx)
wx.why=ttc[1904]..(wx.why or ttc[363])
end
break
end
end
for yx,zx in ipairs(cx)do
if zx.kind==ttc[1587]then
local Ax=cx[1]
if yx>1 and(zx.p or 0)>=0.25 and Ax.kind~=ttc[1586]and Ax.kind~=ttc[1588]and not(Ax.kind==ttc[1454]and Ax.started)and not tostring(Ax.why):find(ttc[1905],1,true)then
table.remove(cx,yx)
table.insert(cx,1,zx)
zx.why=ttc[1906]..(zx.why or ttc[363])
end
break
end
end
local Bx=cx[1]
if Bx and Bx.kind==ttc[1469]and Bx.first then
local Cx,Dx=Bx,(Bx.baseScore or Bx.score)*O.CHAIN_MIN
for Ex=1,6 do
local Fx
for Gx,Hx in ipairs(cx)do
if Hx.kind==ttc[1469]and Hx.first and Hx.diff==Cx.diff and(Hx.baseScore or Hx.score)>=Dx and O.nextAct(Hx.level)==Cx.level then
Fx=Hx
