end
Cx=Fx
end
if Cx~=Bx then
table.remove(cx,table.find(cx,Cx))
table.insert(cx,1,Cx)
Cx.why=ttc[1907]..(Cx.why or ttc[363])
end
end
local Ix=J.testTeam
