function db.run(pM)
local qM=H.session()
local rM=qM and qM.collection:get_unit_by_uuid(pM.uuid)
if not rM then
return
end
if pM.kind==ttc[2055]then
local sM=N.trait(rM)
local tM=sM==ttc[2064]and 1.5 or 1
local uM=math.max(0,db.xpFor(rM.unit_id,db.cap(rM))-(tonumber(rM.xp)or 0))
local vM,wM,xM={},0,0
for yM,zM in ipairs(db.foodHeld())do
local AM=zM.xp*tM
local BM=math.min(zM.n,math.floor((uM-wM)/math.max(1,AM)))
if BM>0 then
vM[zM.id]=BM
wM=wM+BM*AM
xM=xM+BM
end
end
if xM==0 then
J.str.feedNote=pM.name..ttc[2065]
return
end
local CM,DM=tonumber(rM.xp)or 0,db.level(rM)
local EM,FM=j.request(ttc[2055],ttc[2066],pM.uuid,vM)
local GM=M.now()
while M.now()-GM<4 and(tonumber((qM.collection:get_unit_by_uuid(pM.uuid)or rM).xp)or 0)<=CM do
task.wait(0.25)
end
local HM=qM.collection:get_unit_by_uuid(pM.uuid)or rM
local IM=(tonumber(HM.xp)or 0)-CM
if IM>0 then
R.add(string.format(ttc[2067],xM,pM.name),xM,ttc[2068],string.format(ttc[2069],M.fmt(IM),DM,db.level(HM)))
db.note(string.format(ttc[2070],pM.name,xM,M.fmt(IM),DM,db.level(HM),math.abs(IM-wM)>wM*0.1 and string.format(ttc[2071],M.fmt(wM))or ttc[363]))
else
db.note(string.format(ttc[2072],pM.name,tostring(EM and FM or ttc[1698])))
j.backoff(ttc[2055],600)
end
elseif pM.kind==ttc[2060]then
P.fuseInto(pM.uuid,false)
end
end
