local neb=keb*keb
local oeb=W.laneList(heb.samples)~=nil
if oeb then
meb.lanes={}
end
for peb,qeb in ipairs(heb.samples)do
local reb,seb=qeb.pos.X-ieb.X,qeb.pos.Z-ieb.Z
if reb*reb+seb*seb<=neb then
local teb=math.min(W.BINS,math.floor(qeb.prog*W.BINS)+1)
meb[teb]=true
if oeb then
local ueb=tostring(qeb.lane)
meb.lanes[ueb]=meb.lanes[ueb]or{}
