if Ceb then
table.insert(xeb,{u=Aeb,id=Aeb.unit_id,data=Beb,rows=Ceb,cap=N.cap(Aeb),farm=N.isFarm(Aeb.unit_id),placeable=(not Beb.hill_unit)or yeb})
