function W.trust(Smb,Tmb)
local Umb=Smb.cal or{}
if type(Umb.alive)~=ttc[1434]or Umb.teamSig~=W.sig((function()
local Vmb={}
for Wmb,Xmb in ipairs(Tmb)do
table.insert(Vmb,Xmb.u)
end
return Vmb
end)())then
return nil
end
if Smb.key==ttc[1728]and not Umb.aliveLvl then
return nil
end
if Umb.aliveLvl and Smb.ld and Smb.ld.id and Umb.aliveLvl~=tostring(Smb.ld.id)..(eb.is(Smb.ld.id)and(ttc[2641]..tostring(Smb.ld.map))or ttc[363])then
return nil
end
local Ymb=W.run(Smb,Tmb,{hpMul=1})
local Zmb,_mb,anb=0,0,0
for bnb=3,math.min(Ymb.wave,tonumber(Umb.lastWave)or 99)do
local cnb=tonumber(Umb.alive[tostring(bnb)])
local dnb=Ymb.aliveAt[bnb]
if cnb and dnb and cnb>0 then
Zmb=Zmb+cnb
_mb=_mb+dnb
anb=anb+1
end
end
if anb<2 or _mb<=0 then
