local enb=Zmb/_mb
return{ratio=enb,ok=enb>=0.75 and enb<=1.33,waves=anb}
end
W.GROWN_LEVEL,W.GROWN_MIN=50,6
function W.grownKinds()
local fnb=H.session()
local gnb,hnb={},0
for inb,jnb in pairs(fnb.profile_data.collection.owned_units)do
local knb=jnb.unit_id
if not gnb[knb]and H.Units[knb]and not N.isFarm(knb)and N.rows(knb)and not N.hidden(knb)then
local lnb,mnb=pcall(H.USC.calculate_level,knb,tonumber(jnb.xp)or 0)
if lnb and(tonumber(mnb)or 0)>=W.GROWN_LEVEL then
gnb[knb]=true
hnb=hnb+1
end
end
end
return hnb
end
function W.pool(nnb,onb)
local pnb=H.session()
local qnb,rnb={},{}
local snb=W.grownKinds()>=W.GROWN_MIN
for tnb,unb in pairs(pnb.profile_data.collection.owned_units)do
local vnb=pnb.collection:get_unit_by_uuid(unb.uuid)or unb
local wnb,xnb=pcall(H.USC.calculate_level,vnb.unit_id,tonumber(vnb.xp)or 0)
local ynb=N.isFarm(vnb.unit_id)or not snb or(wnb and(tonumber(xnb)or 0)>=W.GROWN_LEVEL)
if H.Units[vnb.unit_id]and N.rows(vnb.unit_id)and not N.hidden(vnb.unit_id)and ynb then
local znb=N.isFarm(vnb.unit_id)
local Anb,Bnb=pcall(znb and function()
return N.farm(vnb,N.rows(vnb.unit_id).max)
end or N.score,vnb,nnb)
Bnb=(Anb and Bnb or 0)*(znb and 1 or N.skinMul(vnb,onb and onb.skinSet))
local Cnb=znb and rnb or qnb
if not Cnb[vnb.unit_id]or Bnb>Cnb[vnb.unit_id].sc then
Cnb[vnb.unit_id]={u=vnb,sc=Bnb}
end
end
end
local Dnb,Enb={},{}
for Fnb,Gnb in pairs(qnb)do
table.insert(Dnb,Gnb)
end
for Hnb,Inb in pairs(rnb)do
table.insert(Enb,Inb)
end
table.sort(Dnb,function(Jnb,Knb)
return Jnb.sc>Knb.sc
end)
table.sort(Enb,function(Lnb,Mnb)
return Lnb.sc>Mnb.sc
end)
local Nnb={}
for Onb=1,math.min(10,#Dnb)do
table.insert(Nnb,Dnb[Onb].u)
end
local Pnb,Qnb={},{}
for Rnb=11,#Dnb do
local Snb=N.rows(Dnb[Rnb].u.unit_id)
for Tnb=0,Snb.max do
if Snb[Tnb]and Snb[Tnb].atk and N.attackInfo(Snb[Tnb].atk,Snb[Tnb].range).dot>0 then
table.insert(Tnb==0 and Pnb or Qnb,Dnb[Rnb].u)
break
end
end
end
for Unb=1,math.min(4,#Pnb)do
table.insert(Nnb,Pnb[Unb])
end
for Vnb=1,math.min(2,#Qnb)do
table.insert(Nnb,Qnb[Vnb])
end
for Wnb=1,math.min(3,#Enb)do
table.insert(Nnb,Enb[Wnb].u)
end
local Xnb={}
for Ynb=11,#Dnb do
local Znb=N.rows(Dnb[Ynb].u.unit_id)[0]
local _nb=Znb and Znb.atk and N.attackInfo(Znb.atk,Znb.range)
if _nb and(_nb.slowTime>0 or _nb.stun>0)then
table.insert(Xnb,Dnb[Ynb].u)
end
end
for aob=1,math.min(3,#Xnb)do
table.insert(Nnb,Xnb[aob])
end
if onb and((onb.flyChance or 0)>0 or onb.mapFly or(onb.shield or 0)>0)then
local bob,cob={},{}
for dob=11,#Dnb do
local eob=Dnb[dob].u
local fob=N.rows(eob.unit_id)[0]
if N.airFrom(eob.unit_id)==0 then
table.insert(bob,eob)
end
local gob,hob=tonumber(fob and fob.cd)or 0,tonumber((H.Units[eob.unit_id]or{}).cost)or 0
if gob>0 and hob>0 and N.range(eob,0)>=15 then
local iob=N.attackInfo(fob.atk,fob.range)
table.insert(cob,{u=eob,v=iob.n*iob.hits/gob/hob*math.min(6,N.cap(eob))})
end
end
table.sort(cob,function(job,kob)
return job.v>kob.v
end)
for lob=1,math.min(4,#bob)do
table.insert(Nnb,bob[lob])
end
for mob=1,math.min(6,#cob)do
table.insert(Nnb,cob[mob].u)
end
end
local nob,oob={},{}
for pob,qob in ipairs(Nnb)do
if not nob[qob]then
nob[qob]=true
table.insert(oob,qob)
end
end
oob.rest={}
for rob,sob in ipairs(Dnb)do
if not nob[sob.u]then
table.insert(oob.rest,sob.u)
end
end
return oob
end
function W.objective(tob)
return(tob.won and 1000 or 0)+tob.wave*10-(tob.won and tob.t/60 or((tob.left or 1)*9-math.min(9,tob.t/60)))
end
W.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function W.cliff(uob,vob,wob)
local xob
for yob,zob in ipairs(W.LADDER)do
xob=W.run(uob,vob,{hpMul=zob,layout=wob})
if not xob.won then
return zob,xob
end
end
return W.LADDER[#W.LADDER],xob
end
function W.exam(Aob,Bob)
local Cob,Dob,Eob=W.teamFrom(Bob,Aob.map),0,0
for Fob,Gob in ipairs(W.LADDER)do
local Hob,Iob=0,0
for Job,Kob in ipairs({0.92,1,1.08})do
local Lob=W.run(Aob,Cob,{hpMul=Gob*Kob})
if Lob.won then
Hob=Hob+1
end
Iob=Iob+Lob.wave
end
Dob,Eob=Dob+Hob,Iob/3
task.wait()
if Hob==0 then
break
end
end
return Dob,Eob
end
W.ZONE_CLOSE,W.ZONE_GAIN=1.3,20
function W.zoneKey(Mob)
return tostring(Mob.key)..ttc[1545]..tostring(Mob.map)
end
function W.zoneChoice(Nob,Oob,Pob,Qob)
if I.killZone==false or Nob.zone or(Nob.infinite and W.unbound(Nob.ld))then
return false
end
local Rob=J.zoneRec[W.zoneKey(Nob)]
local Sob=Rob and(Rob.style==ttc[2625]or(Rob.style==nil and Rob.zone==true))
if Rob and Rob.won then
return Sob==true,Sob and ttc[2642]or nil
end
if Rob and Sob then
return false,ttc[2643]
end
local Tob=J.modes[Nob.key]
local Uob=Tob and tonumber(Tob.streak)or 0
if not Rob and Tob and(tonumber(Tob.wins)or 0)>0 and Uob==0 and Nob.key~=ttc[1728]and Nob.key~=ttc[1724]then
return false
end
local Vob=Rob~=nil or Uob>0
local Wob=Qob and Pob<=1 or(not Qob and Pob<=W.ZONE_CLOSE)
if not(Vob or Wob)then
return false
end
local Xob=table.clone(Nob)
Xob.zone=true
local function Yob(Zob)
