local Npb=Epb and zpb(wpb)==0
for Opb,Ppb in ipairs(tpb)do
local Qpb=false
for Rpb,Spb in ipairs(wpb)do
if Spb.unit_id==Ppb.unit_id then
Qpb=true
end
end
if not Qpb and(not Npb or N.isFarm(Ppb.unit_id))then
local Tpb=table.clone(wpb)
table.insert(Tpb,Ppb)
local Upb=W.run(rpb,W.teamFrom(Tpb,rpb.map),{hpMul=xpb})
local Vpb=W.objective(Upb)
if not Mpb or Vpb>Mpb then
Lpb,Mpb,Kpb=Ppb,Vpb,Upb
