end
local hqb,iqb=Kpb or ypb,dqb(wpb,Kpb or ypb)
if type(tpb.rest)==ttc[1434]and#tpb.rest>0 then
local jqb,kqb
for lqb,mqb in ipairs(wpb)do
if not N.isFarm(mqb.unit_id)and not N.allyBuff(mqb.unit_id)then
local nqb,oqb=pcall(N.score,mqb,rpb.mod)
oqb=(nqb and oqb or 0)*N.skinMul(mqb,rpb.skinSet)
