local Fqb=false
for Gqb,Hqb in ipairs(wpb)do
if Hqb.unit_id==Eqb.unit_id then
Fqb=true
end
end
if not Fqb then
local Iqb=table.clone(wpb)
Iqb[Cqb]=Eqb
