table.insert(Krb,Mrb.unit_id)
end
J.simTeam[krb.key]={uuids=zrb.winTeam,names=Jrb,ids=Krb,won=true,wave=rrb.total,better=W.sig(Brb)~=wrb.sig,cur={won=wrb.won,wave=wrb.wave},at=os.time(),label=krb.label,base=wrb.sig,why=ttc[2653]}
j.log(1,ttc[2647],string.format(ttc[2654],krb.label,table.concat(Jrb,ttc[1530]),Irb and string.format((Hrb.ratio or 0)<0.1 and ttc[2655]or ttc[2656],Hrb.ratio or 0)or string.format(ttc[2657],Grb.wave),zrb.winTeamN or 1))
return wrb
end
end
end
if I.simTeams and lrb then
