function cb.state(pwb)
if pwb._dead then
return ttc[1803]
end
if pwb._finished then
return ttc[2729]
end
local qwb=cb.screens(pwb)[1]
if qwb then
if qwb.t==cb.T.SHOP then
return ttc[2090],qwb
end
if qwb.t==cb.T.OPEN then
return ttc[2730],qwb
end
if qwb.t==cb.T.SHRINE then
return ttc[2680],qwb
end
return ttc[2731],qwb
end
return ttc[2732]
end
function cb.logState(rwb,swb)
local twb={}
for uwb,vwb in pairs(rwb)do
if not cb.KNOWN[uwb]and not(type(vwb)==ttc[1434]and next(vwb)==nil)then
table.insert(twb,tostring(uwb))
end
end
table.sort(twb)
local wwb={}
for xwb,ywb in ipairs(cb.screens(rwb))do
table.insert(wwb,tostring(ywb.t))
end
local zwb=table.concat(twb,ttc[2031])..(#wwb>0 and(ttc[1533]..table.concat(wwb,ttc[2031]))or ttc[363])
if zwb==ttc[363]or J.dg.seen[zwb]then
return
end
J.dg.seen[zwb]=os.time()
local Awb={}
for Bwb,Cwb in ipairs(twb)do
local Dwb=rwb[Cwb]
table.insert(Awb,Cwb..ttc[2476]..(type(Dwb)==ttc[1434]and M.json(M.plain(Dwb)):sub(1,500)or tostring(Dwb)))
end
j.log(1,ttc[2733],ttc[2734]..tostring(swb)..ttc[2735]..table.concat(Awb,ttc[1626]))
j.saveSoon()
end
function cb.note(Ewb)
j.log(1,ttc[2733],Ewb)
table.insert(J.dg.log,1,{at=os.time(),msg=Ewb})
while#J.dg.log>15 do
table.remove(J.dg.log)
end
j.saveSoon()
end
function cb.offers(Fwb,Gwb)
local Hwb={}
if type(Fwb)~=ttc[1434]then
return Hwb
end
for Iwb,Jwb in pairs(Fwb)do
local Kwb,Lwb
if type(Jwb)==ttc[1434]then
Kwb=Jwb.id or Jwb.item_id or Jwb.item
Lwb=tonumber(Jwb.cost)or tonumber(Jwb.price)
elseif type(Jwb)==ttc[1436]then
Kwb=Jwb
elseif cb.item(Iwb)then
Kwb=Iwb
Lwb=tonumber(Jwb)
end
if type(Kwb)==ttc[1436]and cb.item(Kwb)then
table.insert(Hwb,{key=Iwb,id=Kwb,cost=Lwb or tonumber(cb.item(Kwb).cost)or 0,bought=type(Jwb)==ttc[1434]and(Jwb.bought or Jwb.sold or Jwb.purchased)or nil})
end
end
if#Hwb==0 and not Gwb then
for Mwb,Nwb in pairs(Fwb)do
if type(Nwb)==ttc[1434]then
Hwb=cb.offers(Nwb,true)
if#Hwb>0 then
break
end
end
end
end
return Hwb
end
function cb.buy(Owb)
local Pwb=cb.res(cb.data())
local Qwb={}
if J.dg.buyArg==ttc[2591]then
Qwb={Owb.id,Owb.key}
else
Qwb={Owb.key,Owb.id}
end
if Qwb[1]==Qwb[2]then
Qwb[2]=nil
end
for Rwb,Swb in ipairs(Qwb)do
local Twb,Uwb=j.request(ttc[2736],ttc[2737],Swb)
local Vwb=M.now()
while M.now()-Vwb<3 and cb.res(cb.data())>=Pwb do
task.wait(0.25)
end
if cb.res(cb.data())<Pwb then
J.dg.buyArg=(Swb==Owb.id and Owb.id~=Owb.key)and ttc[2591]or ttc[2738]
return true
end
if not Twb then
break
end
end
return false
end
function cb.shopAhead(Wwb)
for Xwb,Ywb in ipairs(cb.rooms(Wwb))do
if Ywb.tags[cb.T.SHOP]then
return true
end
for Zwb,_wb in ipairs(cb.after(Wwb,Ywb.choice))do
if _wb.tags[cb.T.SHOP]then
return true
end
end
end
return false
end
cb.LUCK_RESERVE=500
cb.MIN_WORTH=0.02
cb.TOP_WORTH=0.08
function cb.shop(axb,bxb)
local cxb=cb.cleared(axb)
local dxb=cb.res(axb)
local exb=1+0.1*(cb.items(axb)._curse_shop or 0)
local fxb=cb.shopAhead(axb)and math.ceil(cb.LUCK_RESERVE*exb)or 0
local gxb={}
local hxb,ixb={},0
for jxb,kxb in ipairs(cb.offers(bxb and bxb.data))do
kxb.cost=math.ceil(kxb.cost*exb)
table.insert(hxb,tostring(cb.item(kxb.id).name or kxb.id))
if not kxb.bought and not cb.isCurse(kxb.id)then
kxb.luck=tonumber(cb.item(kxb.id).luck_increase)~=nil
kxb.v=cb.itemValue(kxb.id,axb)
if not kxb.luck and kxb.v/math.max(1,kxb.cost)<cb.MIN_WORTH then
ixb=ixb+1
elseif kxb.v>0 and(kxb.luck or cxb>=10 or kxb.v/math.max(1,kxb.cost)>=cb.TOP_WORTH)then
table.insert(gxb,kxb)
end
end
end
table.sort(gxb,function(lxb,mxb)
if lxb.luck~=mxb.luck then
return lxb.luck
end
return lxb.v/math.max(1,lxb.cost)>mxb.v/math.max(1,mxb.cost)
end)
local nxb,oxb,pxb={},0,0
for qxb,rxb in ipairs(gxb)do
if rxb.cost<=dxb-(rxb.luck and 0 or fxb)then
if cb.buy(rxb)then
dxb=cb.res(cb.data())
table.insert(nxb,string.format(ttc[2739],tostring(cb.item(rxb.id).name or rxb.id),rxb.cost))
end
elseif rxb.cost<=dxb then
pxb=pxb+1
else
oxb=oxb+1
end
end
cb.note(string.format(ttc[2740],cxb,#hxb>0 and table.concat(hxb,ttc[1530])or ttc[2741],#nxb>0 and(ttc[2742]..table.concat(nxb,ttc[1530]))or(cxb<10 and ttc[2743]or(pxb>0 and ttc[2744]or ttc[2745])),dxb,oxb>0 and string.format(ttc[2746],oxb)or ttc[363],pxb>0 and string.format(ttc[2747],pxb,fxb)or ttc[363],ixb>0 and string.format(ttc[2748],ixb)or ttc[363]))
j.request(ttc[2749],ttc[2750])
end
function cb.shrine(sxb,txb)
local uxb=cb.offers(txb and txb.data)
local vxb,wxb=0,{}
local xxb
for yxb,zxb in ipairs(uxb)do
local Axb=cb.item(zxb.id)
table.insert(wxb,tostring(Axb and Axb.name or zxb.id))
if cb.isCurse(zxb.id)then
local Bxb,Cxb,Dxb=pcall(cb.curseOk,zxb.id,sxb,cb.cleared(sxb)+1,nil,cb.rooms(sxb))
if Bxb and not Cxb then
xxb=Dxb
end
else
vxb=vxb+cb.itemValue(zxb.id,sxb)
end
end
local Exb= #uxb>0 and vxb>0 and not xxb
if Exb then
j.request(ttc[2751],ttc[2752])
else
j.request(ttc[2749],ttc[2750])
end
cb.note(string.format(ttc[2753],#wxb>0 and table.concat(wxb,ttc[1530])or ttc[2741],Exb and ttc[2754]or(xxb and(ttc[2755]..xxb)or ttc[2756])))
end
function cb.wallet()
local Fxb=H.session()and H.session().profile_data or{}
local Gxb=Fxb.inventory or{}
local Hxb={gems=tonumber(H.cur(ttc[1494]))or 0,gold=tonumber(H.cur(ttc[1496]))or 0,items={},units={},unique=0}
for Ixb,Jxb in pairs(Gxb.normal_items or{})do
Hxb.items[Ixb]=tonumber(Jxb)or 0
end
for Kxb,Lxb in pairs(Fxb.collection and Fxb.collection.owned_units or{})do
Hxb.units[Kxb]=Lxb.unit_id
end
for Mxb in pairs(Gxb.unique_items or{})do
Hxb.unique=Hxb.unique+1
end
return Hxb
end
function cb.walletDiff(Nxb,Oxb)
local Pxb={}
if Oxb.gems~=Nxb.gems then
table.insert(Pxb,string.format(ttc[2757],Oxb.gems-Nxb.gems))
end
if Oxb.gold~=Nxb.gold then
table.insert(Pxb,string.format(ttc[2758],Oxb.gold-Nxb.gold))
end
for Qxb,Rxb in pairs(Oxb.items)do
if Rxb~=(Nxb.items[Qxb]or 0)then
table.insert(Pxb,string.format(ttc[2759],Rxb-(Nxb.items[Qxb]or 0),tostring(Qxb)))
end
end
for Sxb,Txb in pairs(Oxb.units)do
if not Nxb.units[Sxb]then
table.insert(Pxb,ttc[2760]..N.name(Txb))
end
end
if Oxb.unique~=Nxb.unique then
table.insert(Pxb,string.format(ttc[2761],Oxb.unique-Nxb.unique))
end
return#Pxb>0 and table.concat(Pxb,ttc[1530])or ttc[2762]
end
function cb.openChests(Uxb,Vxb)
local Wxb,Xxb,Yxb=cb.res(Uxb)
local Zxb=cb.lives(Uxb)
local _xb=cb.cleared(Uxb)
if not(Vxb or _xb>=cb.ROOMS or Zxb<=1)then
cb.note(string.format(ttc[2763],_xb,Xxb,Yxb,cb.luck(Uxb)))
