end
local ayb,byb,cyb=0,0,0
local dyb=tonumber(H.cur(ttc[1494]))or 0
local eyb=cb.wallet()
for fyb=1,Xxb+Yxb+4 do
local gyb,hyb,iyb=cb.res(cb.data())
if hyb+iyb<=0 or cyb>=2 then
break
end
local jyb,kyb
if hyb>0 then
jyb,kyb=j.request(ttc[2764],ttc[2765])
else
jyb,kyb=j.request(ttc[2764],ttc[2765],true)
end
if jyb and kyb~=nil then
j.log(1,ttc[2733],ttc[2766]..(type(kyb)==ttc[1434]and M.json(M.plain(kyb)):sub(1,300)or tostring(kyb)))
end
local lyb=M.now()
while M.now()-lyb<4 do
local myb,nyb,oyb=cb.res(cb.data())
if nyb<hyb or oyb<iyb then
break
end
task.wait(0.25)
end
local pyb,qyb,ryb=cb.res(cb.data())
if qyb<hyb then
ayb=ayb+(hyb-qyb)
cyb=0
elseif ryb<iyb then
byb=byb+(iyb-ryb)
cyb=0
else
cyb=cyb+1
end
task.wait(1)
if qyb<hyb or ryb<iyb then
local syb=cb.wallet()
local tyb=cb.walletDiff(eyb,syb)
j.log(1,ttc[2733],(ryb<iyb and ttc[2767]or ttc[2766])..tyb)
J.dg.pay=J.dg.pay or{}
local uyb={}
for vyb,wyb in pairs(syb.items)do
if wyb~=(eyb.items[vyb]or 0)then
uyb[vyb]=wyb-(eyb.items[vyb]or 0)
end
end
table.insert(J.dg.pay,{at=os.time(),rare=ryb<iyb,gems=syb.gems-eyb.gems,luck=cb.luck(Uxb),paid=tyb,items=uyb})
while#J.dg.pay>60 do
table.remove(J.dg.pay,1)
end
eyb=syb
end
end
cb.note(string.format(ttc[2768],ayb,byb,Vxb and ttc[2769]or(Zxb<=1 and ttc[2770]or ttc[2771]),cb.luck(Uxb),(tonumber(H.cur(ttc[1494]))or 0)-dyb))
local xyb,yyb,zyb=cb.res(cb.data())
if(Vxb or _xb>=cb.ROOMS)and yyb+zyb>0 then
cb.note(string.format(ttc[2772],yyb,zyb))
O.rec(ttc[1755]).restUntil=os.time()+1800
return ttc[2773]
end
if not Vxb then
j.request(ttc[2749],ttc[2750])
end
end
function cb.act(Ayb)
local Byb,Cyb=cb.state(Ayb)
cb.logState(Ayb,Byb)
if Byb==ttc[2732]then
return false
end
if Byb==ttc[2731]then
