j.request(ttc[2749],ttc[2750])
return true
end
if Byb==ttc[1803]then
j.request(ttc[2775],ttc[2776])
cb.note(ttc[2777])
J.dg.lives,J.dg.lost=5,{}
elseif Byb==ttc[2729]then
if cb.openChests(Ayb,true)==ttc[2773]then
return ttc[2773]
end
