local Dyb,Eyb,Fyb=cb.res(cb.data())
table.insert(J.dg.runs,1,{at=os.time(),depth=cb.ROOMS,items=M.count(cb.items(Ayb)),left=Eyb+Fyb})
while#J.dg.runs>10 do
table.remove(J.dg.runs)
end
