for wBb=0,vBb-1 do
local xBb=sBb:Lerp(tBb,wBb/vBb)
table.insert(Q.samples,{pos=xBb,prog=(qBb+uBb*wBb/vBb)/math.max(1,oBb),lane=jBb.Name})
end
qBb=qBb+uBb
