end
end
local gOb=cOb and M.flat(cOb-aOb)or Vector3 .new(0,0,-1)
return gOb.Magnitude>0.01 and gOb.Unit or Vector3 .new(0,0,-1)
end
function Q.place(hOb,iOb)
