Q.placeLog=Q.placeLog or{}
table.insert(Q.placeLog,{t=math.floor(M.now()-(Q.startT or M.now())),w=Q.wave(),id=hOb.id,x=math.floor(kOb.X),z=math.floor(kOb.Z),cover=math.floor((lOb or 0)+0.5),why=tostring(iOb):sub(1,90)})
j.status(ttc[2909],string.format(ttc[2924],N.name(hOb.id),iOb))
