if Q.placeFail[hOb.uuid]>=2 then
Q.noSpot[hOb.uuid]=3
j.log(1,ttc[2914],string.format(ttc[2925],N.name(hOb.id),Q.fieldCount(),Q.FIELD_MAX))
end
end
if nOb and mOb>=(hOb.data.cost or 0)and not Q.random then
local pOb=Q.spotKey(kOb)
Q.refused[pOb]=true
local qOb=Q.mapKey()
J.blocked[qOb]=J.blocked[qOb]or{}
if not Q.refusedRun[pOb]then
J.blocked[qOb][pOb]=(tonumber(J.blocked[qOb][pOb])or 0)+1
Q.refusedRun[pOb]=true
end
Q.refusals=(Q.refusals or 0)+1
Q.unitRefusals[hOb.uuid]=(Q.unitRefusals[hOb.uuid]or 0)+1
if Q.unitRefusals[hOb.uuid]>=3 then
local rOb=math.max(1,Q.count(hOb.uuid))
if J.caps[hOb.uuid]~=rOb then
J.caps[hOb.uuid]=rOb
j.log(1,ttc[2914],string.format(ttc[2926],N.name(hOb.id),rOb))
end
end
j.log(2,ttc[2914],ttc[2927]..pOb..ttc[1963]..N.name(hOb.id))
j.saveSoon()
end
return false
end
